            elif isinstance(current, bool):
                setattr(self, field_name, False)
            elif isinstance(current, str):
                setattr(self, field_name, '')
            elif isinstance(current, (list, dict)):
                if isinstance(current, list):
                    setattr(self, field_name, [])
                else:
                    setattr(self, field_name, {})
            else:
                setattr(self, field_name, Decimal('0'))
        else:
            setattr(self, field_name, Decimal('0'))

